<?php
namespace App\Http\Controllers;
use App\Models\ShortLink; use App\Models\SmartTarget; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Illuminate\View\View;
class SmartTargetController extends Controller { public function index(ShortLink $link):View{return view('smart-targets.index',compact('link'));} public function store(Request $request,ShortLink $link):RedirectResponse{$d=$request->validate(['name'=>['required','string','max:100'],'destination_url'=>['required','url:http,https'],'condition_type'=>['required','in:device,language,country'],'condition_value'=>['required','string','max:100'],'priority'=>['nullable','integer','min:1','max:999']]);$link->smartTargets()->create($d+['is_active'=>true]);return back()->with('success',__('Smart target added.'));} public function destroy(ShortLink $link,SmartTarget $target):RedirectResponse{abort_unless($target->short_link_id===$link->id,404);$target->delete();return back()->with('success',__('Smart target removed.'));} }
